#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# AI 開発チーム（docs/superpowers/specs/agent-team.md）の GitHub 名義をそろえる手順書。
# 実装担当の GitHub App pelway-dev と、レビュー担当の GitHub App pelway-review を作り、
# 認証情報を ~/.config/pelway-agent/fnox.toml（age で暗号化）に置き、ブランチ保護と Projects ボードを設定する。
# scripts/agent-gh はこの設定から認証情報を読む。

REPO="hatai/Pelway"
REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
CFG="${PELWAY_AGENT_FNOX_CONFIG:-$HOME/.config/pelway-agent/fnox.toml}"
NOTIFY_CFG="$HOME/.config/pelway-agent-notify/fnox.toml"
ENV_FILE="/nonexistent/pelway-agent-accounts.env" # 値は .env ではなく fnox に置く

# fnox_set NAME：標準入力の値を CFG に age で暗号化して保存する（値は argv に載せない）。
fnox_set() {
  fnox -c "$CFG" set --provider age "$1" >/dev/null
  printf '  %s✓ saved%s %s → %s\n' "$GREEN" "$RESET" "$1" "$CFG"
}

# App の作成・秘密鍵の保存・インストールを 3 段階で案内する。
# app_stages <名前> <fnox の接頭辞> <役割の説明> <権限の説明>
app_stages() {
  local name="$1" prefix="$2" role="$3" perms="$4" slug_var="$2_SLUG" id_var="$2_ID_INPUT" inst_var="$2_INSTALLATION_INPUT" key_var="$2_KEY_PATH" slug

  stage "GitHub App $name を作る"
  say "$role の名義。hatai でログインしたブラウザで作業する。"
  open_url "https://github.com/settings/apps/new"
  step "GitHub App name: $name（使われていたら別名にし、下の warn を読む）"
  step "Homepage URL: https://github.com/$REPO"
  step "Webhook: Active のチェックを外す"
  step "Repository permissions: $perms（Metadata は自動で Read-only）"
  step "Where can this GitHub App be installed?: Only on this account → Create GitHub App"
  warn "名前が $name 以外になった場合は、CI（verify.yml）と skill の $name を合わせて直す必要がある。"
  step "作成後の General ページに出る App ID と、URL の /settings/apps/<slug> の slug を控える。"
  ask "$id_var" "App ID:"
  ask "$slug_var" "slug（URL の apps/ の後ろ）:"
  printf '%s' "${!id_var}" | fnox_set "${prefix}_APP_ID"
  pause

  slug="${!slug_var}"
  stage "$slug の秘密鍵を保存する"
  open_url "https://github.com/settings/apps/$slug"
  step "General ページ下部の Private keys → Generate a private key。.pem ファイルがダウンロードされる。"
  note "WSL からは /mnt/c/Users/<Windows のユーザー名>/Downloads/... で見える。"
  ask "$key_var" "ダウンロードした .pem のパス:"
  [[ -f "${!key_var}" ]] || { warn "${!key_var} が見つからない"; exit 1; }
  fnox_set "${prefix}_APP_KEY" <"${!key_var}"
  if confirm "保存したので、ダウンロードした ${!key_var} を削除する？"; then
    rm -f -- "${!key_var}"
    printf '  %s✓ removed%s %s\n' "$GREEN" "$RESET" "${!key_var}"
  else
    SKIPPED+=("${!key_var} を削除する")
  fi
  pause

  stage "$slug を $REPO にインストールする"
  open_url "https://github.com/apps/$slug/installations/new"
  step "Only select repositories → $REPO を選ぶ → Install"
  step "インストール後の URL https://github.com/settings/installations/<数字> の数字を控える。"
  ask "$inst_var" "Installation ID（URL の数字）:"
  printf '%s' "${!inst_var}" | fnox_set "${prefix}_APP_INSTALLATION_ID"
  pause
}

run_wizard() {

TOTAL_STAGES=11

banner "Pelway AI 開発チームの GitHub 名義とブランチ保護"

stage "gh 拡張 gh-token を入れる"
say "実装担当とレビュー担当（どちらも GitHub App）のトークンは gh 拡張 Link-/gh-token で発行する。"
if gh extension list 2>/dev/null | grep -q "gh-token"; then
  note "インストール済み"
elif confirm "gh extension install Link-/gh-token を実行する？"; then
  gh extension install Link-/gh-token
else
  SKIPPED+=("gh extension install Link-/gh-token")
fi
pause

stage "認証情報の置き場所を作る"
say "認証情報は $CFG に age で暗号化して置く。リポジトリには入らない。"
if [[ -f "$CFG" ]]; then
  note "作成済み"
else
  mkdir -p "$(dirname "$CFG")"
  recipients=""
  [[ -f "$NOTIFY_CFG" ]] && recipients="$(grep -E '^recipients' "$NOTIFY_CFG" | head -n1 || true)"
  if [[ -z "$recipients" ]]; then
    warn "pelway-agent-notify の age 公開鍵が見つからない"
    step "age の公開鍵（age1... で始まる）を用意する。秘密鍵は ~/.config/fnox/age.txt に置く。"
    ask AGE_RECIPIENT "age の公開鍵:"
    recipients="recipients = [\"$AGE_RECIPIENT\"]"
  else
    note "pelway-agent-notify と同じ age 公開鍵を使う"
  fi
  (umask 077 && cat >"$CFG" <<EOF
# Pelway AI 開発チームの GitHub 名義（scripts/agent-gh が読む）。値は age で暗号化されている。
# 作成と更新: scripts/setup/agent-accounts.sh
[providers.age]
type = "age"
$recipients

[secrets]
EOF
  )
  printf '  %s✓ created%s %s\n' "$GREEN" "$RESET" "$CFG"
fi
pause

app_stages "pelway-dev" "PELWAY_DEV" "実装担当のエージェントが push と PR 作成に使う" \
  "Contents = Read and write / Pull requests = Read and write / Issues = Read and write / Workflows = Read and write（.github/workflows を直す PR の push に必要）"

# コミットの作成者に使うメールアドレス（<bot ユーザーの ID>+<slug>[bot]@users.noreply.github.com）
dev_bot_id="$(gh api "/users/${PELWAY_DEV_SLUG}%5Bbot%5D" --jq .id)"
printf '%s' "$dev_bot_id+${PELWAY_DEV_SLUG}[bot]@users.noreply.github.com" | fnox_set PELWAY_DEV_GIT_EMAIL

app_stages "pelway-review" "PELWAY_REVIEW" "レビュー担当のエージェントがレビューを投稿するのに使う" \
  "Contents = Read-only / Pull requests = Read and write / Issues = Read-only"

stage "名義を確かめる"
say "scripts/agent-gh で、それぞれの名義が GitHub に通るか確かめる。"
for role in dev review; do
  repos="$(bash "$REPO_ROOT/scripts/agent-gh" "$role" api /installation/repositories --jq '.repositories[].full_name' || true)"
  if [[ "$repos" == *"$REPO"* ]]; then
    printf '  %s✓%s %s → %s にアクセスできる\n' "$GREEN" "$RESET" "$role" "$REPO"
  else
    warn "$role のトークンで $REPO にアクセスできない"
    SKIPPED+=("scripts/agent-gh $role の確認")
  fi
done
pause

stage "main のブランチ保護を有効にする"
say "CODEOWNERS（* @hatai）による人間の Approve と、CI の mise run verify・pr-size の成功を必須にする。"
warn "このリポジトリ側の変更（CODEOWNERS と CI の pr-size）が main にマージされてから実行する。"
if confirm "main にマージ済み。scripts/setup/branch-protection.sh を実行する？"; then
  bash "$REPO_ROOT/scripts/setup/branch-protection.sh"
else
  SKIPPED+=("bash scripts/setup/branch-protection.sh")
fi
pause

stage "Projects ボードを作る"
say "進捗の正本になるボード。組み込みワークフローで PR の状態を列に反映する。"
open_url "https://github.com/hatai?tab=projects"
step "New project → Board → 名前 Pelway agent team"
step "Status の選択肢を Todo / Working / In review / Changes requested / Ready to merge / Done にする"
step "右上の … → Workflows で次を有効にする:"
note "  Auto-add to project: リポジトリ $REPO、フィルタ is:issue label:ready-for-agent"
note "  Item closed → Done / Pull request merged → Done"
note "  Code changes requested → Changes requested / Code review approved → Ready to merge"
step "Settings → Manage access ではなく、リポジトリの Projects タブからこのボードをリンクする"
open_url "https://github.com/$REPO/projects"
pause "終わったら Enter"

finish
}

run_wizard "$@"; exit
